import {metrics,apertures,shutters,focalStops,nearest,clamp,shutterText,distanceText,meteredEV} from './physics.mjs';
import {drawIris,pupilPath,pupilTransmission,shutterFrame} from './pupil.mjs';
import {drawCutaway} from './camera-view.mjs';
import {drawPhoto} from './renderer.mjs';
import {getLanguage} from './i18n.mjs';
import {portraitExample} from './journey.mjs';

export const learningText=(de,en)=>getLanguage()==='en'?en:de;
export function createOptics(api){
 const el=document.createElement('dialog');el.id='optics-dialog';document.body.append(el);
 let kind='aperture',guide=null,guideHome=null,playing=false,phase=.45,last=0,photoHit=null,irisDrag=false,renderKey='';
 const text=learningText,$=id=>el.querySelector('#'+id);
 const shapes=()=>[['circle',text('Runde Referenz','Round reference')],['iris',text('Irisblende','Iris diaphragm')],['heart',text('Herzmaske','Heart mask')],['bat',text('Fledermausmaske','Bat mask')]];
 function range(id,label,min,max,step){return `<label class="optic-field">${label}<output id="${id}-value"></output><input id="${id}" type="range" min="${min}" max="${max}" step="${step}"></label>`;}
 function build(){
  if(guide?.parentElement?.closest('#optics-dialog'))return;
  el.innerHTML=`<header class="optic-header"><div><span class="eyebrow">${text('OPTIKLABOR · GEMEINSAME KAMERA','OPTICS LAB · ONE SHARED CAMERA')}</span><h2>${text('Die Kamera von innen verstehen','Understand the camera from within')}</h2></div><form method="dialog"><button class="close" aria-label="${text('Schließen','Close')}">×</button></form></header><div class="optic-mode" role="group" aria-label="${text('Vertiefung','Explore in depth')}"><button data-opt-kind="aperture">${text('Blende & Bokeh','Aperture & bokeh')}</button><button data-opt-kind="shutter">${text('Verschluss & Zeit','Shutter & time')}</button><button id="opt-example">${text('Beispielaufbau laden','Load example scene')}</button></div><div id="opt-guide-host"></div><div class="optic-workspace"><section class="optic-theory"><div class="optic-pupil-row" id="opt-pupil-row"><figure><figcaption>${text('Frontansicht · Öffnung ziehen','Front view · drag the opening')}</figcaption><canvas id="opt-iris" width="400" height="300" tabindex="0" role="slider" aria-label="${text('Blendenöffnung ziehen oder mit Pfeiltasten verstellen','Drag the aperture opening or use arrow keys')}" aria-valuemin="1.4" aria-valuemax="22"></canvas></figure><figure><figcaption>${text('Ein defokussierter Lichtpunkt','One defocused light source')}</figcaption><canvas id="opt-spot" width="400" height="300" role="img" aria-label="${text('Vergrößerter geometrischer Lichtfleck auf dem Sensor','Enlarged geometrical light spot on the sensor')}"></canvas></figure></div><figure id="opt-shutter-figure" hidden><figcaption>${text('Zwei Vorhänge vor dem Sensor · Zeitlupe','Two curtains in front of the sensor · slow motion')}</figcaption><canvas id="opt-shutter" width="800" height="440" role="img" aria-label="${text('Vereinfachter Schlitzverschluss','Simplified focal-plane shutter')}"></canvas><div class="shutter-phase"><button id="opt-play">${text('Ablauf abspielen','Play sequence')}</button><label>${text('Phase','Phase')}<input id="opt-phase" type="range" min="0" max="1" step=".005" value=".45"></label></div></figure><figure class="optic-rays"><figcaption>${text('Dieselbe Kamera · idealisiertes Zwei-Gruppen-Modell','The same camera · idealised two-group model')}</figcaption><canvas id="opt-rays" width="900" height="410"></canvas></figure></section><aside class="optic-photo-aside"><figure class="optic-photo-frame"><figcaption>${text('Aufnahme · dieselben Einstellungen','Capture · the same settings')}</figcaption><canvas id="opt-photo" width="900" height="600" aria-label="${text('Gemeinsame simulierte Aufnahme; Motiv anklicken zum Fokussieren','Shared simulated capture; click a subject to focus')}"></canvas></figure><div class="optic-comparison"><button id="opt-remember">${text('A merken','Remember A')}</button><button id="opt-compare" disabled>${text('A/B vergleichen','Compare A/B')}</button></div><div id="opt-readout" class="optic-readout" aria-live="polite"></div><p id="opt-explanation" class="optic-explanation"></p><details class="optic-more"><summary>${text('Mehr Optik & Modellgrenzen','More optics & model limits')}</summary><p>${text('N = f/D: D ist der Durchmesser der Eintrittspupille, also das von vorn gesehene Bild der Blende. Die mechanische Öffnung und die Pupille sind bei realen Objektiven nicht unbedingt gleich groß.','N = f/D: D is the entrance-pupil diameter, the image of the iris seen from the front. The mechanical opening and pupil need not be the same size in a real lens.')}</p><p>${text('Die exakt fokussierte Ebene bleibt eine Ebene. Abblenden verkleinert geometrische Defokusflecken. Bei sehr kleiner Öffnung setzt Beugung der Auflösung Grenzen — eine Lochkamera macht nicht automatisch alles perfekt scharf.','The exactly focused plane remains a plane. Stopping down reduces geometrical defocus spots. Very small openings introduce diffraction limits: a pinhole camera does not automatically make everything perfectly sharp.')}</p><p>${text('Pupillenformen werden hier achsnah und geometrisch übertragen. Der Lichtfleck ist stark vergrößert, mit festem Maßstab. Konturen ganzer Objekte bleiben weichgezeichnete 2,5D-Lagen. Abbildungsfehler, Katzenaugen, Zwiebelringe, Randlichtabfall und eine vollständige Wellenoptik fehlen. Bokeh bezeichnet mehr als nur die Fleckform. Vor und hinter der Fokusebene kehrt sich die geometrische Pupillenabbildung um.','Pupil shapes are transferred geometrically near the optical axis. The light spot is strongly magnified at a fixed scale. Whole objects remain softened 2.5D layers. Aberrations, cat-eye shapes, onion rings, vignetting and full wave optics are omitted. Bokeh means more than the highlight shape. The geometrical pupil image reverses across the focus plane.')}</p><p>${text('Die gezeichneten Lamellen zeigen eine schematische Iris, keinen Fertigungsplan. Gerade Lamellen bleiben im Modell polygonal. Motivmasken sind eigene Formblenden; ihre Größe wird mit D skaliert. Eine feste Vorsatzmaske plus separate Iris wird nicht kombiniert. Masken kosten entsprechend ihrer offenen Fläche Licht; A kompensiert mit längerer Zeit. Der geometrische Unschärfedurchmesser nutzt die umschreibende runde Pupille.','The drawn blades are a schematic iris, not a manufacturing drawing. Straight blades stay polygonal in this model. Shaped masks are separate aperture stops scaled with D. A fixed front mask plus an independent iris is not combined. Masks lose light according to their open area; A compensates with longer exposure. The geometrical blur diameter uses the enclosing circular pupil.')}</p><p>${text('Verschlussmodell: beispielhafte Vorhanglaufzeit 4 ms, keine Messung einer bestimmten Kamera. Elektronische und Zentralverschlüsse werden hier nicht nachgebildet.','Shutter model: illustrative 4 ms curtain transit, not a measurement of a specific camera. Electronic and leaf shutters are not modelled here.')}</p><p><a href="https://www.edmundoptics.com/knowledge-center/application-notes/imaging/lens-iris-aperture-setting/" target="_blank" rel="noopener">Edmund Optics · f/#</a> · <a href="https://www.nikonusa.com/learn-and-explore/c/tips-and-techniques/bokeh-for-beginners" target="_blank" rel="noopener">Nikon · Bokeh</a> · <a href="https://www.sony.co.uk/electronics/support/articles/00018997" target="_blank" rel="noopener">Sony · ${text('Verschlussvorhänge','Shutter curtains')}</a></p></details></aside><div class="optic-controls"><div data-opt-aperture>${range('opt-N',text('Blendenzahl','Aperture'),0,apertures.length-1,1)}</div><div data-opt-shutter hidden>${range('opt-time',text('Belichtungszeit','Shutter speed'),0,shutters.length-1,1)}</div>${range('opt-focal',text('Brennweite','Focal length'),0,focalStops.length-1,1)}${range('opt-focus',text('Fokusdistanz','Focus distance'),.3,30,.1)}${range('opt-depth',text('Lichtpunkt-Entfernung','Light-source distance'),1,40,.1)}<label class="optic-field" data-opt-aperture>${text('Pupillenform','Pupil shape')}<select id="opt-shape">${shapes().map(([id,name])=>`<option value="${id}">${name}</option>`).join('')}</select></label><label class="optic-field" data-opt-aperture>${text('Lamellen','Blades')}<select id="opt-blades">${[5,6,7,9,11].map(n=>`<option value="${n}">${n}</option>`).join('')}</select></label><div class="optic-checks"><label><input id="opt-rounded" type="checkbox">${text('Gerundete Lamellen','Rounded blades')}</label><label><input id="opt-lights" type="checkbox">${text('Lichtpunkte im Foto','Light sources in photo')}</label><label><input id="opt-compensate" type="checkbox">${text('Automatische Belichtung','Automatic exposure')}</label></div></div></div>`;
  el.querySelectorAll('[data-opt-kind]').forEach(b=>b.onclick=()=>setKind(b.dataset.optKind));
  $('opt-remember').onclick=()=>{api.remember(api.state());sync();};$('opt-compare').onclick=()=>{const a=api.comparisonA();if(a)api.compare(a,api.state());};
  $('opt-example').onclick=()=>api.replace({...portraitExample,aperture:kind==='aperture'?2.8:4,pupilShape:kind==='aperture'?'iris':'circle',bladeCount:5,...(kind==='shutter'?{mode:'S',autoISO:true,time:1/30,motion:true,speed:3,focal:50}:{})});
  const input=(id,fn)=>$(id).oninput=()=>{api.change(fn(Number($(id).value)));};
  input('opt-N',v=>({aperture:apertures[v]}));input('opt-time',v=>({time:shutters[v],mode:$('opt-compensate').checked?'S':'M',autoISO:$('opt-compensate').checked}));input('opt-focal',v=>({focal:focalStops[v]}));input('opt-focus',v=>({focus:v,autoFocus:false}));input('opt-depth',v=>({background:v-api.state().cameraBack}));
  $('opt-shape').onchange=()=>api.change({pupilShape:$('opt-shape').value});$('opt-blades').onchange=()=>api.change({bladeCount:Number($('opt-blades').value),pupilShape:'iris'});$('opt-rounded').onchange=()=>api.change({roundedBlades:$('opt-rounded').checked,pupilShape:'iris'});$('opt-lights').onchange=()=>api.change({bokehLights:$('opt-lights').checked});$('opt-compensate').onchange=()=>api.change({mode:$('opt-compensate').checked?(kind==='shutter'?'S':'A'):'M',autoISO:kind==='shutter'&&$('opt-compensate').checked});
  $('opt-play').onclick=()=>{playing=!playing;phase=phase>=1?0:phase;last=performance.now();sync();};$('opt-phase').oninput=()=>{playing=false;phase=Number($('opt-phase').value);sync();render(true);};
  const iris=$('opt-iris');function irisValue(e){const r=iris.getBoundingClientRect(),x=e.clientX-r.left-r.width/2,y=e.clientY-r.top-r.height*.49,radius=Math.hypot(x,y),outer=Math.min(r.width*.39,r.height*.36);api.change({aperture:nearest(apertures,clamp(1.4*.91*outer/Math.max(radius,2),1.4,22))});}
  iris.onpointerdown=e=>{irisDrag=true;iris.setPointerCapture(e.pointerId);irisValue(e);};iris.onpointermove=e=>{if(irisDrag)irisValue(e);};iris.onpointerup=iris.onpointercancel=()=>irisDrag=false;
  iris.onkeydown=e=>{const i=apertures.indexOf(nearest(apertures,metrics(api.state()).s.aperture));let next=i;if(e.key==='ArrowUp'||e.key==='ArrowRight')next=Math.min(i+1,apertures.length-1);else if(e.key==='ArrowDown'||e.key==='ArrowLeft')next=Math.max(0,i-1);else if(e.key==='Home')next=0;else if(e.key==='End')next=apertures.length-1;else return;e.preventDefault();api.change({aperture:apertures[next]});};
  $('opt-photo').onpointerdown=e=>{const r=$('opt-photo').getBoundingClientRect(),id=photoHit?.pickAt?.((e.clientX-r.left)*$('opt-photo').width/r.width,(e.clientY-r.top)*$('opt-photo').height/r.height);if(id)api.focus(id);};
  for(const cv of el.querySelectorAll('canvas'))new ResizeObserver(()=>{if(el.open)render(true);}).observe(cv);
  setKind(kind);sync();
 }
 function setKind(next){kind=next==='shutter'?'shutter':'aperture';el.dataset.kind=kind;el.querySelectorAll('[data-opt-kind]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.optKind===kind)));el.querySelectorAll('[data-opt-aperture]').forEach(n=>n.hidden=kind!=='aperture');el.querySelectorAll('[data-opt-shutter]').forEach(n=>n.hidden=kind!=='shutter');$('opt-pupil-row').hidden=kind!=='aperture';$('opt-shutter-figure').hidden=kind!=='shutter';renderKey='';render(true);}
 function sync(){if(!$('opt-N'))return;const m=metrics(api.state()),s=m.s;
  for(const [id,value,formatted]of[['opt-N',apertures.indexOf(nearest(apertures,s.aperture)),`ƒ/${Number(s.aperture.toFixed(1))}`],['opt-time',shutters.indexOf(nearest(shutters,s.time)),shutterText(s.time)],['opt-focal',focalStops.indexOf(nearest(focalStops,s.focal)),`${Number(s.focal.toFixed(1))} mm`],['opt-focus',s.focus,distanceText(s.focus)],['opt-depth',s.background+s.cameraBack,distanceText(s.background+s.cameraBack)]]){$(id).value=value;$(id).setAttribute('aria-valuetext',formatted);$(id+'-value').textContent=formatted;}
  $('opt-focus').max=Math.max(30,s.focus);$('opt-depth').max=Math.max(40,s.background+s.cameraBack);$('opt-shape').value=s.pupilShape;$('opt-blades').value=String(s.bladeCount);$('opt-blades').disabled=['heart','bat'].includes(s.pupilShape);$('opt-rounded').disabled=['heart','bat'].includes(s.pupilShape);$('opt-rounded').checked=s.roundedBlades;$('opt-lights').checked=s.bokehLights;$('opt-compensate').checked=s.mode!=='M'||s.autoISO;$('opt-N').disabled=s.sensor==='phone';$('opt-iris').setAttribute('aria-disabled',String(s.sensor==='phone'));$('opt-iris').setAttribute('aria-valuenow',String(s.aperture));$('opt-iris').setAttribute('aria-valuetext',`ƒ/${s.aperture}`);$('opt-phase').value=phase;$('opt-play').textContent=playing?text('Pause','Pause'):text('Ablauf abspielen','Play sequence');
  $('opt-compare').disabled=!api.comparisonA();
  const b=m.blurAt(s.background+s.cameraBack);$('opt-readout').innerHTML=`<span>ƒ/${Number(s.aperture.toFixed(1))} · ${s.focal.toFixed(1)} mm</span><span>D = ${m.apertureDiameter.toFixed(1)} mm</span><span>${text('Defokus','Defocus')} ${b.toFixed(3)} mm</span><span>${text('Offene Fläche','Open area')} ${Math.round(pupilTransmission(s)*100)} %</span><span>${shutterText(s.time)} · ISO ${Math.round(s.iso)}</span><span>ΔEV ${m.offset.toFixed(1)}</span>${(s.mode!=='M'||s.autoISO)&&Math.abs(m.offset+meteredEV(s)-s.ev-s.comp)>.35?'<span class="optic-limit">'+text('Automatikgrenze erreicht','Exposure limit reached')+'</span>':''}`;
  $('opt-explanation').textContent=kind==='shutter'?text((s.sensor==='phone'?'Smartphone: Die tatsächliche Integration erfolgt elektronisch. Hier siehst du einen mechanischen Vergleichsverschluss. ':'')+'Belichtungszeit gilt pro Zeile. Ein kurzer Spalt kann den Sensor zeilenweise belichten, obwohl der ganze Ablauf länger dauert.',(s.sensor==='phone'?'Smartphone: actual integration is electronic. This is a mechanical comparison model. ':'')+'Exposure duration applies per row. A narrow slit exposes the sensor row by row while the complete sequence takes longer.'):b<m.coc?text('Der Lichtpunkt liegt innerhalb des gewählten Schärfekriteriums. Die Pupillenform ist dann kaum erkennbar. Fokussiere vor den Hintergrund, um ihre Form zu sehen.','The light source is within the selected sharpness criterion. The pupil shape is barely visible. Focus in front of the background to reveal it.'):text('Der Lichtpunkt liegt außerhalb des Fokus. Seine Strahlen treffen den Sensor als Fläche: Ihre Größe folgt dem Defokus, ihre Form der wirksamen Öffnung.','The light source is out of focus. Its rays reach the sensor as an area: size follows defocus, shape follows the effective opening.');if(s.sensor==='phone'&&kind==='aperture')$('opt-explanation').textContent=text('Smartphone: ƒ/1.8 ist fest. Beispielaufbau laden wechselt zu Vollformat. ','Smartphone: f/1.8 is fixed. Load example scene switches to full frame. ')+$('opt-explanation').textContent;
 }
 function canvasFit(cv){const r=cv.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,1.5),w=Math.max(1,Math.round(r.width*d)),h=Math.max(1,Math.round(r.height*d));if(cv.width!==w||cv.height!==h){cv.width=w;cv.height=h;}return {c:cv.getContext('2d'),W:w,H:h,d};}
 function panelBase(cv){const o=canvasFit(cv),dark=document.documentElement.dataset.theme==='dark';o.dark=dark;o.c.fillStyle=dark?'#152920':'#f0f4e8';o.c.fillRect(0,0,o.W,o.H);o.c.fillStyle=dark?'#cee3d4':'#456254';o.c.font=`${12*o.d}px system-ui`;o.c.textAlign='center';return o;}
 function render(force=false,t=api.time()){
  if(!el.open)return;sync();const raw=api.state(),m=metrics(raw),s=m.s,key=JSON.stringify(raw)+'|'+getLanguage()+'|'+document.documentElement.dataset.theme+'|'+kind+'|'+t;if(!force&&key===renderKey&&!(playing&&kind==='shutter'))return;renderKey=key;
  if(kind==='aperture'){const a=panelBase($('opt-iris')),r=Math.min(a.W*.39,a.H*.36);drawIris(a.c,a.W/2,a.H*.49,r,s,{dark:a.dark});a.c.fillStyle=a.dark?'#cee3d4':'#456254';a.c.fillText(`ƒ/${Number(s.aperture.toFixed(1))} · D = ${m.apertureDiameter.toFixed(1)} mm`,a.W/2,a.H*.96);
   const b=panelBase($('opt-spot')),blur=m.blurAt(s.background+s.cameraBack),scale=160*b.d,radius=Math.max(1.3*b.d,blur*scale/2);b.c.save();b.c.translate(b.W/2,b.H*.49);const sign=s.background+s.cameraBack>s.focus?-1:1;b.c.scale(sign,sign);pupilPath(b.c,0,0,radius,s);b.c.fillStyle='#dca954';b.c.fill();b.c.restore();b.c.beginPath();b.c.arc(b.W/2,b.H*.49,Math.max(1,m.coc*scale/2),0,7);b.c.strokeStyle=b.dark?'#9ce2cb':'#24735e';b.c.setLineDash([3*b.d,3*b.d]);b.c.stroke();b.c.setLineDash([]);b.c.fillStyle=b.dark?'#cee3d4':'#456254';b.c.fillText(text('Detail · 1 mm = 160 px','Detail · 1 mm = 160 px'),b.W/2,b.H*.91);b.c.fillText(text('gestrichelt: Schärfekriterium','dashed: sharpness criterion'),b.W/2,b.H*.98);
  }else{const o=panelBase($('opt-shutter')),c=o.c,x=o.W*.23,y=o.H*.11,w=o.W*.49,h=o.H*.69,f=shutterFrame(phase,s.time);c.fillStyle='#7ab49e';c.fillRect(x,y,w,h);for(let i=0;i<9;i++){c.strokeStyle='#bce2cb88';c.beginPath();c.moveTo(x,y+i*h/8);c.lineTo(x+w,y+i*h/8);c.stroke();}c.fillStyle='#384e49';c.fillRect(x,y+f.front*h,w,h*(1-f.front));c.fillStyle='#bd9860';c.fillRect(x,y,w,f.rear*h);for(let i=0;i<6;i++){c.strokeStyle='#ffffff30';c.strokeRect(x,y+f.front*h+i*h/6,w,h/6);c.strokeRect(x,y+f.rear*h-i*h/6,w,-h/6);}c.strokeStyle=o.dark?'#cee3d4':'#456254';c.strokeRect(x,y,w,h);c.fillStyle=o.dark?'#cee3d4':'#456254';c.fillText(text('Sensor · grün = gerade belichtet','Sensor · green = currently exposed'),o.W/2,o.H*.87);c.fillText(`${text('Pro Zeile','Per row')}: ${shutterText(s.time)} · ${text('Vorhanglauf','Curtain transit')}: 4 ms`,o.W/2,o.H*.96);}
  canvasFit($('opt-rays'));drawCutaway($('opt-rays'),raw,{active:kind==='shutter'?'time':'aperture'});canvasFit($('opt-photo'));photoHit=drawPhoto($('opt-photo'),raw,t,{fast:api.animating?.()});
 }
 function attachGuide(){if(guide){if(!guideHome){guideHome=document.createComment('guide home');guide.before(guideHome);}$('opt-guide-host').append(guide);}}
 el.addEventListener('close',()=>{playing=false;if(guideHome){guideHome.replaceWith(guide);guideHome=null;}api.onClose?.();});el.addEventListener('click',e=>{const r=el.getBoundingClientRect();if(e.target===el&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))el.close();});
 document.addEventListener('camera-language-change',()=>{if(!el.open)build();else render(true);});
 function tick(now){if(el.open&&!document.hidden){if(playing&&kind==='shutter'){const dt=Math.min(.1,(now-last)/1000);phase=(phase+dt/4)%1;render(true);}last=now;if(api.moving())render(false);}requestAnimationFrame(tick);}build();requestAnimationFrame(tick);
 return {open(next='aperture'){if(!el.open){build();setKind(next);el.showModal();attachGuide();if(next==='shutter'&&api.animating?.()&&!matchMedia('(prefers-reduced-motion: reduce)').matches){playing=true;phase=0;last=performance.now();}}else setKind(next);renderKey='';render(true);},close(){if(el.open)el.close();},get isOpen(){return el.open;},get kind(){return kind;},update(){if(el.open)render(false);},guide(node){guide=node;if(el.open)attachGuide();},element:el};
}
